"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6386],{34412:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Creates a new Fader under `parent`.","params":[{"name":"parent","desc":"Where the `AudioFader` instance is created","lua_type":"Instance"},{"name":"props","desc":"`Name`, and a starting `Volume` (clamped to 0 - 3)","lua_type":"{ Name: string?, Volume: number? }?"}],"returns":[{"desc":"","lua_type":"Fader"}],"function_type":"static","source":{"line":114,"path":"src/Orchestra/Components/Fader.luau"}},{"name":"Set","desc":"Sets the volume immediately, cancelling any running fade. While muted, the volume is stored for when you unmute.","params":[{"name":"volume","desc":"0 (silent) to 3, where 1 is unchanged","lua_type":"number"}],"returns":[],"function_type":"method","source":{"line":155,"path":"src/Orchestra/Components/Fader.luau"}},{"name":"Tween","desc":"Tweens the volume to `goal`. While muted, the goal is stored for when you unmute and the Promise resolves right away.","params":[{"name":"goal","desc":"Target volume, 0 - 3","lua_type":"number"},{"name":"tweenInfo","desc":"Defaults to a 1 second linear tween","lua_type":"TweenInfo?"}],"returns":[{"desc":"Resolves when the tween completes, cancelled when interrupted or the Fader is destroyed","lua_type":"Promise"}],"function_type":"method","source":{"line":190,"path":"src/Orchestra/Components/Fader.luau"}},{"name":"FadeOut","desc":"Fades the volume down linearly over `duration` seconds.","params":[{"name":"duration","desc":"Seconds, greater than 0","lua_type":"number"},{"name":"goal","desc":"Target volume, 0 - 3. Defaults to 0","lua_type":"number?"}],"returns":[{"desc":"See [Fader:Tween]","lua_type":"Promise"}],"function_type":"method","source":{"line":249,"path":"src/Orchestra/Components/Fader.luau"}},{"name":"FadeIn","desc":"Fades the volume up linearly over `duration` seconds.","params":[{"name":"duration","desc":"Seconds, greater than 0","lua_type":"number"},{"name":"goal","desc":"Target volume, 0 - 3. Defaults to 1","lua_type":"number?"}],"returns":[{"desc":"See [Fader:Tween]","lua_type":"Promise"}],"function_type":"method","source":{"line":269,"path":"src/Orchestra/Components/Fader.luau"}},{"name":"Mute","desc":"Toggles mute. Muting fades to 0 over 0.5 seconds and remembers the volume; calling it again fades back to that volume.","params":[{"name":"noTween","desc":"Cut immediately instead of fading","lua_type":"boolean?"}],"returns":[{"desc":"Resolves when the fade completes, right away with `noTween`","lua_type":"Promise"}],"function_type":"method","source":{"line":288,"path":"src/Orchestra/Components/Fader.luau"}},{"name":"Destroy","desc":"Destroys the Fader: its instance, and every wire into or out of it.\\nDestroying the instance directly does the same.","params":[],"returns":[],"function_type":"method","source":{"line":322,"path":"src/Orchestra/Components/Fader.luau"}}],"properties":[{"name":"Instance","desc":"The wrapped `AudioFader` instance.","lua_type":"AudioFader","readonly":true,"source":{"line":71,"path":"src/Orchestra/Components/Fader.luau"}},{"name":"Routing","desc":"Wires this Fader to others, see [Routing].","lua_type":"Routing","readonly":true,"source":{"line":79,"path":"src/Orchestra/Components/Fader.luau"}},{"name":"In","desc":"The instance to wire into (same as `Instance`).","lua_type":"AudioFader","readonly":true,"source":{"line":87,"path":"src/Orchestra/Components/Fader.luau"}},{"name":"Out","desc":"The instance to wire from (same as `Instance`).","lua_type":"AudioFader","readonly":true,"source":{"line":95,"path":"src/Orchestra/Components/Fader.luau"}},{"name":"IsMuted","desc":"Whether the Fader is muted with [Fader:Mute].","lua_type":"boolean","readonly":true,"source":{"line":103,"path":"src/Orchestra/Components/Fader.luau"}}],"types":[],"name":"Fader","desc":"Wraps an `AudioFader`, which controls the volume of everything wired through it (0 - 3, where 1 is unchanged).\\nThe mix buses and Master created by [Orchestra:Start] are Faders too.\\n\\n`Tween`, `FadeIn`, `FadeOut` and `Mute` return a [Promise](https://eryn.io/roblox-lua-promise/) that resolves when the\\nfade completes. Starting another `Tween` / `Set`, or destroying the Fader, cancels it instead and leaves the volume\\nwhere it was.\\n\\n```lua\\nmusic.Fader:FadeOut(2):andThen(function()\\n\\tmusic:Stop()\\nend)\\n```","tags":["Base"],"source":{"line":63,"path":"src/Orchestra/Components/Fader.luau"}}')}}]);